"'+yy+'\" x2=\"'+(W-R)+'\" y2=\"'+yy+'\" stroke=\"#e9edf5\" stroke-dasharray=\"4 5\"/>'}).join('');return '<svg viewBox=\"0 0 '+W+' '+H+'\" role=\"img\" aria-label=\"نمودار میله‌ای هفت روز اخیر\" class=\"chart-svg\">'+grid+bars+'</svg>'}\nfunction renderReports(){ $('countFoods').textContent=fmt(S.logs.length);$('countSessions').textContent=fmt(S.sessions.length);$('countMeasures').textContent=fmt(S.measures.length);\nlet w=S.measures.filter(x=>x.weight_kg&&x.measured_on).slice().sort((a,b)=>a.measured_on.localeCompare(b.measured_on)).slice(-12).map(x=>({v:Number(x.weight_kg),label:jdate(x.measured_on)}));$('weightTrend').innerHTML=lineChart(w,'کیلوگرم','#7668e8');\nlet days=[];for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);let key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');days.push({key,label:new Intl.DateTimeFormat('fa-IR',{weekday:'short'}).format(d)})}\nlet cal=days.map(d=>{let rows=S.logs.filter(x=>x.consumed_on===d.key);return {v:rows.length?rows.reduce((n,x)=>n+(Number(x.energy_kcal)||0),0):0,label:d.label,hasData:rows.length>0}});$('calorieTrend').innerHTML=cal.some(p=>p.hasData)?barChart(cal.map(p=>({...p,v:p.hasData?p.v:0})),'#20a681'):chartEmpty('هنوز برای ۷ روز اخیر ثبت غذایی ندارید.');\nlet workouts=days.map(d=>({v:S.sessions.filter(x=>x.session_date===d.key).length,label:d.label}));$('workoutTrend').innerHTML=workouts.some(p=>p.v>0)?barChart(workouts,'#e6a23c'):chartEmpty('پس از ثبت جلسه تمرینی، نمودار هفتگی اینجا نمایش داده می‌شود.');\nlet a=S.logs.filter(x=>x.consumed_on===today()),sum=k=>a.reduce((n,x)=>n+(Number(x[k])||0),0);$('nutritionReport').innerHTML='<div class=\"macro\"><div><small>انرژی</small><b>'+fmt(sum('energy_kcal'))+'</b></div><div><small>پروتئین</small><b>'+fmt(sum('protein_g'))+' g</b></div><div><small>کربوهیدرات</small><b>'+fmt(sum('carbohydrate_g'))+' g</b></div><div><small>چربی</small><b>'+fmt(sum('fat_g'))+' g</b></div></div><p class=\"muted\">بر اساس '+fmt(a.length)+' ثبت امروز؛ مقادیر تخمینی ممکن است جمع را ناقص کنند.</p>';list('activityReport',S.sessions.slice(0,5).map(x=>'<div class=\"item\"><b>تمرین: '+esc(x.title)+'</b><p class=\"muted\">'+jdate(x.session_date)+'</p></div>').join('')||'هنوز جلسه تمرینی ثبت نشده است.')}\n\n$('refresh').onclick=()=>load().then(()=>toast('گزارش به‌روز شد.')).catch(x=>toast(errText(x),true));\n(async()=>{try{let r=await db.auth.getSession();if(r.data.session)await init();else authView()}catch(e){authView();toast(errText(e),true)}})();\ndb.auth.onAuthStateChange((ev,session)=>{if(ev==='SIGNED_OUT'){S.user=null;authView()}else if(session&&(!S.user||S.user.id!==session.user.id))setTimeout(()=>init(),0)});\n</script></body></html>";
